using System.Globalization;
using System.Reflection;

[AttributeUsage(AttributeTargets.Method)]
public sealed class CommandAttribute(string name, string description) : Attribute
{
    public string Name { get; } = name;
    public string Description { get; } = description;
}

public class CommandConsole
{
    private readonly object _target;
    private readonly Dictionary<string, (MethodInfo Method, CommandAttribute Info)> _commands = new();

    public CommandConsole(object target)
    {
        _target = target;
        foreach (var method in target.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance))
        {
            var info = method.GetCustomAttribute<CommandAttribute>();
            if (info is null) continue;
            if (_commands.ContainsKey(info.Name)) throw new InvalidOperationException($"two commands named {info.Name}");
            _commands[info.Name] = (method, info);
        }
    }

    private static string Usage(string name, MethodInfo method) =>
        string.Join(" ", new[] { name }.Concat(method.GetParameters().Select(p => p.HasDefaultValue ? $"[{p.Name}]" : p.Name!)));

    public string Run(string line)
    {
        var words = line.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries);
        if (words.Length == 0) return "";
        string name = words[0];

        if (name == "help")
        {
            return string.Join("\n", _commands.OrderBy(c => c.Key, StringComparer.Ordinal)
                .Select(c => $"{Usage(c.Key, c.Value.Method)}: {c.Value.Info.Description}"));
        }

        if (!_commands.TryGetValue(name, out var command)) return $"unknown command: {name}";
        var parameters = command.Method.GetParameters();
        var given = words.Skip(1).ToArray();
        int required = parameters.Count(p => !p.HasDefaultValue);
        if (given.Length < required || given.Length > parameters.Length) return $"usage: {Usage(name, command.Method)}";

        var args = new object?[parameters.Length];
        for (int i = 0; i < parameters.Length; i++)
        {
            if (i >= given.Length)
            {
                args[i] = parameters[i].DefaultValue;
                continue;
            }
            try
            {
                args[i] = Convert.ChangeType(given[i], parameters[i].ParameterType, CultureInfo.InvariantCulture);
            }
            catch (Exception e) when (e is FormatException or InvalidCastException or OverflowException)
            {
                return $"bad value for {parameters[i].Name}: {given[i]}";
            }
        }

        object? result = command.Method.Invoke(_target, args);
        return Convert.ToString(result, CultureInfo.InvariantCulture) ?? "";
    }
}

unitTests:
Test("running commands", () =>
{
    var c = new CommandConsole(new Tools());
    CheckEq(c.Run("add 2 40"), "42");
    CheckEq(c.Run("  greet   Ada  "), "hello Ada");
    CheckEq(c.Run("greet Ada true"), "HELLO ADA!");
    CheckEq(c.Run("half 5"), "2.5");
    CheckEq(c.Run("noop"), "");
    CheckEq(c.Run(""), "");
});

Test("help", () =>
{
    CheckEq(new CommandConsole(new Tools()).Run("help"),
        "add a b: Adds two whole numbers\ngreet name [shout]: Says hello\nhalf x: Halves a number\nnoop: Does nothing");
});

Test("bad input is reported", () =>
{
    var c = new CommandConsole(new Tools());
    CheckEq(c.Run("subtract 1 2"), "unknown command: subtract");
    CheckEq(c.Run("add 1"), "usage: add a b");
    CheckEq(c.Run("add 1 2 3"), "usage: add a b");
    CheckEq(c.Run("add one 2"), "bad value for a: one");
    CheckEq(c.Run("greet Ada maybe"), "bad value for shout: maybe");
});

Test("duplicate names", () =>
{
    CheckThrows<InvalidOperationException>(() => new CommandConsole(new Twice()));
});

