    public int Add(int a, int b) => a + b;

    [Command("greet", "Says hello")]
    public string Greet(string name, bool shout = false) => shout ? $"HELLO {name.ToUpper()}!" : $"hello {name}";

    [Command("half", "Halves a number")]
    public double Half(double x) => x / 2;

    [Command("noop", "Does nothing")]
    public void Noop() { }

    public int NotACommand() => 0;
}

public class Twice
{
    [Command("x", "one")] public void A() { }
    [Command("x", "two")] public void B() { }
}
